import json, sys, time, urllib.error, urllib.request
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP

BASE = 'http://localhost:8080'
START = datetime(2025, 3, 1, tzinfo=timezone.utc)
END = datetime(2025, 6, 1, tzinfo=timezone.utc)

token = None
token_fetches = 0
rate_limits = 0

def fetch_token():
    global token, token_fetches
    for attempt in range(1, 31):
        try:
            req = urllib.request.Request(BASE + '/token', method='POST')
            with urllib.request.urlopen(req, timeout=20) as resp:
                data = json.load(resp)
            token = data['token']
            token_fetches += 1
            return
        except urllib.error.HTTPError as e:
            body = e.read().decode('utf-8', 'replace')
            wait = e.headers.get('Retry-After')
            if e.code == 429:
                try:
                    wait = float(wait)
                except (TypeError, ValueError):
                    try:
                        wait = float(json.loads(body).get('retry_after'))
                    except Exception:
                        wait = 1.0
                print(f'token rate-limited; waiting {wait}s', file=sys.stderr)
                time.sleep(wait)
            else:
                print(f'token HTTP {e.code}; retrying: {body}', file=sys.stderr)
                time.sleep(min(attempt, 5))
        except Exception as e:
            print(f'token error {e"'!r}; retrying'"', file=sys.stderr)
            time.sleep(min(attempt, 5))
    raise RuntimeError('could not obtain token')

def get(path):
    global rate_limits
    if token is None:
        fetch_token()
    for attempt in range(1, 61):
        try:
            req = urllib.request.Request(BASE + path, headers={'Authorization': 'Bearer ' + token})
            with urllib.request.urlopen(req, timeout=30) as resp:
                return json.load(resp)
        except urllib.error.HTTPError as e:
            body = e.read().decode('utf-8', 'replace')
            if e.code == 401:
                print('token expired; fetching a replacement and repeating request', file=sys.stderr)
                fetch_token()
                continue
            if e.code == 429:
                rate_limits += 1
                wait = e.headers.get('Retry-After')
                try:
                    wait = float(wait)
                except (TypeError, ValueError):
                    try:
                        parsed = json.loads(body)
                        wait = float(parsed.get('retry_after', parsed.get('wait', 1)))
                    except Exception:
                        wait = 1.0
                print(f'rate-limited on {path}; waiting {wait}s then repeating', file=sys.stderr)
                time.sleep(wait)
                continue
            if 500 <= e.code < 600:
                print(f'HTTP {e.code} on {path}; repeating request', file=sys.stderr)
                time.sleep(min(attempt, 5))
                continue
            if e.code == 404:
                raise RuntimeError(f'404 on {path}: {body}')
            print(f'HTTP {e.code} on {path}: {body}; repeating request', file=sys.stderr)
            time.sleep(min(attempt, 5))
        except (urllib.error.URLError, TimeoutError) as e:
            print(f'transient error on {path}: {e}; repeating request', file=sys.stderr)
            time.sleep(min(attempt, 5))
    raise RuntimeError(f'gave up on {path}')

fetch_token()
orders = {}
listed = 0
pages = 0
status_counts = {}
path = '/orders?page=1'
visited_paths = set()
while path:
    if path in visited_paths:
        raise RuntimeError('pagination loop at ' + path)
    visited_paths.add(path)
    data = get(path)
    pages += 1
    items = data.get('items', [])
    listed += len(items)
    for order in items:
        oid = order['id']
        status_counts[order.get('status')] = status_counts.get(order.get('status'), 0) + 1
        if oid not in orders:
            orders[oid] = order
    if data.get('next') is None:
        path = None
    else:
        path = data['next']

customer_cache = {}
by_region = {r: 0 for r in ('north', 'south', 'east', 'west')}
qualifying = []
for order in orders.values():
    if order.get('status') "'!= '"'shipped':
        continue
    placed = datetime.fromisoformat(order['placed_at'].replace('Z', '+00:00')).astimezone(timezone.utc)
    if not (START <= placed < END):
        continue
    cid = order['customer_id']
    if cid not in customer_cache:
        customer_cache[cid] = get('/customers/' + urllib.parse.quote(str(cid), safe=''))
    customer = customer_cache[cid]
    discount = int(customer['discount_pct'])
    amount = int(order['amount_cents'])
    numerator = amount * (100 - discount)
    discounted = int((Decimal(numerator) / Decimal(100)).quantize(Decimal('1'), rounding=ROUND_HALF_UP))
    region = customer['region']
    if region not in by_region:
        raise RuntimeError('unexpected region: ' + repr(region))
    by_region[region] += discounted
    qualifying.append((order['id'], placed.isoformat(), amount, discount, discounted, region))

result = {
    'total_cents': sum(by_region.values()),
    'order_count': len(qualifying),
    'duplicates_skipped': listed - len(orders),
    'by_region': by_region,
}
print(json.dumps({'result': result, 'diagnostics': {
    'pages': pages, 'listed': listed, 'unique_orders': len(orders),
    'status_counts_including_duplicates': status_counts,
    'cached_customers': len(customer_cache), 'token_fetches': token_fetches,
    'rate_limits': rate_limits,
}}, sort_keys=True, indent=2))
